/** Generation and validation of the short board key that prefixes issue ids (e.g. `WEB-12`). */
object BoardKeys {
    private val VALID = Regex("^[A-Z][A-Z0-9]{1,9}$")

    /** Key used when a name has no ASCII letters at all (e.g. a Persian-only name). */
    const val FALLBACK = "BRD"

    /**
     * Derives a key from a board [name]: initials of up to three words, or the first three
     * letters of a single word; ASCII letters only, uppercase, at least two characters.
     */
    fun generate(name: String): String {
        val words = name.trim().split(Regex("[^A-Za-z0-9]+")).filter { it.isNotEmpty() && it.first().isLetter() }
        val raw = when {
            words.isEmpty() -> FALLBACK
            words.size == 1 -> words[0].take(3)
            else -> words.take(3).joinToString("") { it.take(1) }
        }.uppercase()
        return if (raw.length >= 2) raw else raw.padEnd(2, 'X')
    }

    /** @return true when [key] is 2-10 chars, starts with a letter, uppercase letters/digits only. */
    fun isValid(key: String): Boolean = VALID.matches(key)

    /** @return [candidate] uppercased/trimmed when valid, otherwise a key generated from [fallbackName]. */
    fun normalizeOrGenerate(candidate: String?, fallbackName: String): String {
        val c = candidate?.trim()?.uppercase().orEmpty()
        return if (isValid(c)) c else generate(fallbackName)
    }
}

/** Pure helpers for ordering items inside a column / the list of columns. */
object Ordering {
    /**
     * Returns [items] with [item] removed and re-inserted at [index] (clamped to the valid range).
     * If [item] is not in [items] it is simply inserted.
     */
    fun <T> moveTo(items: List<T>, item: T, index: Int): List<T> {
        val without = items.filterNot { it == item }
        val at = index.coerceIn(0, without.size)
        return without.take(at) + item + without.drop(at)
    }

    /** @return a map from each element to its index (0..n-1), i.e. the new `position` values. */
    fun <T> positions(items: List<T>): Map<T, Int> = items.mapIndexed { i, t -> t to i }.toMap()
}

/**
